/* From Uiverse.io by PriyanshuGupta28 - Tags: input, rating, Rating Button, start rating */
.__UIV_SCOPE__ .rating {
  display: flex;
  flex-direction: row-reverse;
 /* Reverse the order of the stars */
  font-size: 0;
 /* Remove the space between the elements */
}

.__UIV_SCOPE__ .rating input[type="radio"] {
  display: none;
 /* Hide the radio buttons */
}

.__UIV_SCOPE__ .rating label {
  font-size: 30px;
  color: rgba(187, 183, 183, 0.726);
 /* Empty star color */
  margin: 0 2px;
  cursor: pointer;
}

.__UIV_SCOPE__ .rating label:before {
  content: "\2605";
 /* Unicode character for filled star */
}

.__UIV_SCOPE__ .rating input[type="radio"]:checked ~ label:before {
  content: "\2606";
 /* Unicode character for empty star */
  color: #016bf5;
 /* Filled star color */
}
